import java.util.List;
import org.apache.lucene.document.Field;
import org.apache.lucene.document.LatLonShape;
import org.apache.lucene.document.ShapeField;
import org.apache.lucene.geo.Polygon;
import org.apache.lucene.geo.Tessellator;

public class Inspect {
  public static void main(String[] args) {
    double[] lons = new double[] {-0.001, -0.001, 0.001, 0.001, -0.001};
    double[] lats = new double[] {1e-10, 0, -1e-10, 0, 1e-10};
    Polygon polygon = new Polygon(lats, lons);
    List<Tessellator.Triangle> ts = Tessellator.tessellate(polygon, true);
    System.out.println("tessellated triangles: " + ts.size());
    int i = 0;
    for (Tessellator.Triangle t : ts) {
      System.out.println("T" + (i++) + " " + t);
    }
    System.out.println("indexed fields:");
    Field[] fs = LatLonShape.createIndexableFields("f", polygon);
    i = 0;
    for (Field f : fs) {
      byte[] b = f.binaryValue().bytes;
      ShapeField.DecodedTriangle dt = new ShapeField.DecodedTriangle();
      ShapeField.decodeTriangle(b, dt);
      System.out.println(
          "F"
              + (i++)
              + " type="
              + dt.type
              + " a=("
              + dt.aX
              + ","
              + dt.aY
              + ") b=("
              + dt.bX
              + ","
              + dt.bY
              + ") c=("
              + dt.cX
              + ","
              + dt.cY
              + ") flags=("
              + dt.ab
              + ","
              + dt.bc
              + ","
              + dt.ca
              + ")");
    }
  }
}

